import { createHash, randomBytes, timingSafeEqual } from "node:crypto";

const sha256 = (text: string) => createHash("sha256").update(text).digest();

export const newCapability = () => {
  const capability = randomBytes(32).toString("hex");
  return { capability, digest: sha256(capability) };
};

export const matches = (presented: string, digest: Buffer) =>
  timingSafeEqual(sha256(presented), digest);

export class SecretInOutput extends Error {}

export const guard = (text: string, secrets: string[]) => {
  for (const secret of secrets) {
    if (secret && text.includes(secret)) throw new SecretInOutput("refused: output contains a secret");
  }
  return text;
};

