import { createServer } from "node:http";
import { matches, newCapability } from "./capability.js";

const { capability, digest } = newCapability();
console.log("capability (shown once):", capability);

const bearer = (header: string | undefined) => header?.replace(/^Bearer /, "") ?? "";

createServer((req, res) => {
  if (req.url === "/health") return void res.end("ok");
  if (!matches(bearer(req.headers.authorization), digest)) return void res.writeHead(401).end("unauthorized");
  res.end("hello, run for RH-1234");
}).listen(8080, () => console.log("listening on :8080"));
